        const otherAuthNamespaces = HelpersUtil/* HelpersUtil */.y.getOtherAuthNamespaces(connectResult?.connectedCaipNetwork?.chainNamespace);
        const activeCaipNetwork = ChainController/* ChainController */.W.state.activeCaipNetwork;
